package com.example.storytv;
import android.annotation.TargetApi;import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.*;import android.media.tv.TvContract;import android.net.Uri;import android.os.*;import android.util.Log;import java.io.*;import java.util.Calendar;
final class StreakChannel {
 private static final String PREFS="tv_channel";private static final String TAG="StoryTimeChannel";
 static void refreshAsync(final Context context){if(Build.VERSION.SDK_INT<26)return;final Context app=context.getApplicationContext();new Thread(new Runnable(){public void run(){refresh(app);}}).start();}
 @TargetApi(26) static synchronized void refresh(Context c){try{c.getContentResolver().notifyChange(Uri.parse("content://com.example.storytv.streakart/status"),null);android.content.SharedPreferences p=c.getSharedPreferences(PREFS,Context.MODE_PRIVATE);ContentResolver resolver=c.getContentResolver();long channel=p.getLong("channel",-1),program=p.getLong("program",-1);Intent launch=new Intent(c,MainActivity.class).setAction(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);String target=launch.toUri(Intent.URI_INTENT_SCHEME);
 if(channel<0){if(p.getBoolean("created",false))return;ContentValues values=new ContentValues();values.put(TvContract.Channels.COLUMN_TYPE,TvContract.Channels.TYPE_PREVIEW);values.put(TvContract.Channels.COLUMN_DISPLAY_NAME,"Story Time");values.put(TvContract.Channels.COLUMN_APP_LINK_INTENT_URI,target);Uri uri=resolver.insert(TvContract.Channels.CONTENT_URI,values);if(uri==null)return;channel=ContentUris.parseId(uri);p.edit().putLong("channel",channel).putBoolean("created",true).apply();try{OutputStream out=resolver.openOutputStream(TvContract.buildChannelLogoUri(channel));int id=c.getResources().getIdentifier("story_logo","drawable",c.getPackageName());Bitmap logo=BitmapFactory.decodeResource(c.getResources(),id);if(out!=null){logo.compress(Bitmap.CompressFormat.PNG,100,out);out.close();}logo.recycle();}catch(Exception e){Log.w(TAG,"Channel logo unavailable",e);}}
 else {try(Cursor cur=resolver.query(TvContract.buildChannelUri(channel),new String[]{TvContract.Channels._ID},null,null,null)){if(cur==null||!cur.moveToFirst())return;}}
 int streak=StoryProgress.streak(c);String poster="content://"+c.getPackageName()+".streakart/streak?day="+System.currentTimeMillis()/86400000L+"&v=2&count="+streak;ContentValues card=new ContentValues();card.put(TvContract.PreviewPrograms.COLUMN_CHANNEL_ID,channel);card.put(TvContract.PreviewPrograms.COLUMN_TYPE,TvContract.PreviewPrograms.TYPE_CLIP);card.put(TvContract.PreviewPrograms.COLUMN_TITLE,streak+" day reading streak");card.put(TvContract.PreviewPrograms.COLUMN_SHORT_DESCRIPTION,"Open Story Time and read today!");card.put(TvContract.PreviewPrograms.COLUMN_POSTER_ART_URI,poster);card.put(TvContract.PreviewPrograms.COLUMN_POSTER_ART_ASPECT_RATIO,TvContract.PreviewPrograms.ASPECT_RATIO_16_9);card.put(TvContract.PreviewPrograms.COLUMN_INTENT_URI,target);card.put(TvContract.PreviewPrograms.COLUMN_INTERNAL_PROVIDER_ID,"reading_streak");
 if(program<0){Uri added=resolver.insert(TvContract.PreviewPrograms.CONTENT_URI,card);if(added!=null){program=ContentUris.parseId(added);p.edit().putLong("program",program).apply();TvContract.requestChannelBrowsable(c,channel);}}else{Uri uri=TvContract.buildPreviewProgramUri(program);resolver.update(uri,card,null,null);}
 schedule(c);
 }catch(Exception e){Log.w(TAG,"TV home channel unavailable on this launcher",e);}}
 private static void schedule(Context c){Calendar next=Calendar.getInstance();next.add(Calendar.DAY_OF_MONTH,1);next.set(Calendar.HOUR_OF_DAY,0);next.set(Calendar.MINUTE,1);next.set(Calendar.SECOND,0);next.set(Calendar.MILLISECOND,0);Intent i=new Intent(c,StreakRefreshReceiver.class).setAction("com.example.storytv.REFRESH_STREAK");PendingIntent pi=PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager alarm=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);if(alarm!=null)alarm.set(AlarmManager.RTC,next.getTimeInMillis(),pi);}
}
